"use client";
import { useEffect, useState } from "react";
import {
  X,
  Clock,
  AlertCircle,
  MessageCircle,
  Link,
  Phone,
} from "lucide-react";
import { pushEvent } from "@/src/utils/dataLayer";
import { MdArrowForward } from "react-icons/md";

interface VisitorStatus {
  status: "active" | "blocked" | "registered";
  stage?: number;
  remainingMs?: number;
  expiryTime?: string;
  isBlocked: boolean;
  registered: boolean;
  message?: string;
  stageLabel?: string;
}

const stageContent: Record<
  number,
  {
    heading: string;
    description: string;
    sub: string;
    button: string;
  }
> = {
  1: {
    heading: "মাথা নষ্ট ডিসকাউন্ট!",
    description: "মাত্র ১৯৯ টাকায়! ",
    sub: "৫,০০০ টাকার লাইভ ওয়ার্কশপ! অফারটি শেষ হতে আর মাত্র কিছু সময় বাকি",
    button: "১৯৯ টাকায় এখনই জয়েন করুন",
  },
  2: {
    heading: "আপনি কি অফারটি মিস করেছেন?",
    description: "আপনার জন্য কিছু সময় বাড়ানো হলো!",
    sub: "",
    button: "দ্রুত জয়েন করুন",
  },
  3: {
    heading: "সর্বশেষ সতর্কতা!",
    description: "অফারটি বন্ধ হচ্ছে",
    sub: "১৯৯ টাকা নাকি ৫,০০০ টাকা? সিদ্ধান্ত আপনার।",
    button: "১৯৯ টাকায় এখনই জয়েন করুন",
  },
};

const DEFAULT_PHONE_NUMBER = "8801700999093";

const formatLocalPhone = (num: string) => {
  const clean = num.replace(/[^\d]/g, "");
  if (clean.startsWith("880") && clean.length === 13)
    return "0" + clean.slice(3);
  return clean;
};

interface Props {
  siteData?: {
    whatsappNumber?: string;
  } | null;
}

export default function ExclusiveTimerPopup({ siteData }: Props) {
  const [status, setStatus] = useState<VisitorStatus | null>(null);
  const [showPopup, setShowPopup] = useState(true);
  const [timeLeft, setTimeLeft] = useState({
    hours: 0,
    minutes: 0,
    seconds: 0,
  });

  const phoneNumber = siteData?.whatsappNumber || DEFAULT_PHONE_NUMBER;
  const waLink = `https://wa.me/${phoneNumber}`;
  const telLink = `tel:+${phoneNumber.replace(/[^\d]/g, "")}`;
  const displayPhone = formatLocalPhone(phoneNumber);

  useEffect(() => {
    const API_URL =
      process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000/api/v1";

    fetch(`${API_URL}/exclusive/visitor-status`, {
      credentials: "include",
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          setStatus(data);
          if (data.status === "registered") {
            setShowPopup(false);
          }
        }
      })
      .catch((error) => {
        console.error("Error fetching visitor status:", error);
      });
  }, []); 

  
  useEffect(() => {
    if (!status || status.status !== "active" || !status.remainingMs) return;

    // Use backend expiry time
    const expiry = new Date(status.expiryTime!);

    const interval = setInterval(() => {
      const remaining = Math.max(0, expiry.getTime() - Date.now());

      if (remaining <= 0) {
        clearInterval(interval);
        window.location.reload();
        return;
      }

      const hours = Math.floor(remaining / (1000 * 60 * 60));
      const minutes = Math.floor((remaining % 3600000) / 60000);
      const seconds = Math.floor((remaining % 60000) / 1000);
      setTimeLeft({ hours, minutes, seconds });
    }, 1000);

    return () => clearInterval(interval);
  }, [status]);

  const getActiveStage = (): number => {
    // Use backend stage (no dev override)
    return status?.stage || 1;
  };

  const getIsBlocked = (): boolean => {
    return status?.status === "blocked";
  };

  const getIsRegistered = (): boolean => {
    return status?.status === "registered";
  };

  const handleRegister = () => {
    // ✅ GTM Event: add_to_cart
    pushEvent("add_to_cart", {
      ecommerce: {
        currency: "BDT",
        value: 199,
        items: [
          {
            item_id: "exclusive_offer_199",
            item_name: "Voice & Public Speaking Masterclass",
            item_category: "exclusive_offer",
            price: 199,
            quantity: 1,
          },
        ],
      },
    });

    setShowPopup(false);
    const el = document.getElementById("registration-form");
    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  // Close current popup (does not affect timer)
  const handleClose = () => {
    setShowPopup(false);
  };

  if (getIsRegistered()) return null;
  if (!showPopup) return null;

  // === BLOCKED STATE ===
  if (getIsBlocked()) {
    return (
      <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-md p-4">
        <div className="relative overflow-hidden max-w-md w-full rounded-3xl border border-orange-500/20 bg-gradient-to-br from-[#1B1B1B] via-[#121212] to-black shadow-[0_25px_80px_rgba(249,115,22,0.25)]">
          {/* Background Glow */}
          <div className="absolute top-0 -right-10 h-48 w-48 rounded-full bg-orange-500/20 blur-3xl" />
          <div className="absolute -bottom-20 -left-20 h-40 w-40 rounded-full bg-yellow-400/10 blur-3xl" />

          {/* Close */}
          <button
            onClick={handleClose}
            className="absolute top-4 right-4 z-10 flex h-10 w-10 items-center justify-center rounded-full border border-white/10 bg-white/5 text-gray-400 transition-all duration-300 hover:bg-orange-500 hover:text-white"
          >
            <X className="w-5 h-5" />
          </button>

          <div className="relative p-4 text-center">
            {/* Icon */}
            <div className="mx-auto mb-3 flex h-14 w-14 items-center justify-center rounded-full bg-gradient-to-br from-orange-500 to-amber-400 shadow-xl shadow-orange-500/40">
              <AlertCircle className="h-10 w-10 text-white" />
            </div>

            {/* Title */}
            <h2 className="text-2xl md:text-3xl font-extrabold leading-tight text-white">
              ১৯৯ টাকার অফারটি শেষ!
            </h2>

            {/* Price */}
            <div className="mt-2 rounded-2xl border border-orange-500/20 bg-white/5 p-3">
              <p className="text-sm text-gray-400">বর্তমান কোর্স ফি</p>

              <p className="mt-1 text-3xl font-extrabold text-orange-400">
                ৫,০০০ টাকা
              </p>
            </div>

            {/* Description */}
            <p className="mt-4 text-[15px] leading-7 text-gray-300">
              আপনি চাইলে বিশেষ অনুরোধে এখনও কোনো সুযোগ আছে কি না জানতে আমাদের
              সাথে সরাসরি যোগাযোগ করতে পারেন।
            </p>

            {/* WhatsApp Button */}
            <Link
              href={waLink}
              target="_blank"
              // rel="noopener noreferrer"
              className="flex items-center justify-center gap-2 w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-6 rounded-full shadow-lg transition transform hover:scale-[1.02]"
            >
              <MessageCircle className="w-5 h-5" />
              হোয়াটসঅ্যাপে মেসেজ করুন
            </Link>

            {/* Phone */}
            <Link
              href={telLink}
              className="mt-4 flex w-full items-center justify-center gap-3 rounded-2xl border border-orange-500/20 bg-white/5 px-5 py-3 transition-all duration-300 hover:border-orange-400 hover:bg-orange-500/10 hover:shadow-lg hover:shadow-orange-500/20"
            >
              <div className="flex h-11 w-11 items-center justify-center rounded-full bg-gradient-to-br from-orange-500 to-amber-400">
                <Phone className="h-5 w-5 text-white" />
              </div>

              <div className="text-left">
                <p className="text-xs uppercase tracking-[0.2em] text-gray-400">
                  অথবা কল করুন
                </p>

                <p className="text-xl font-bold tracking-wide text-orange-300">
                  {displayPhone}
                </p>
              </div>
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // === ACTIVE STAGES ===
  const stage = getActiveStage();
  const content = stageContent[stage] || stageContent[1];

  return (
    <>
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
      <div className="relative bg-gradient-to-br from-orange-600/90 to-black rounded-2xl p-6 max-w-md w-full shadow-2xl border border-orange-500/30">
        <button
          onClick={handleClose}
          className="absolute top-2 right-2 text-white/70 hover:text-white"
        >
          <X className="w-5 h-5" />
        </button>

        <div className="text-center">
          <div className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full border border-orange-500/30 bg-orange-500/10 mb-4">
            <Clock className="w-4 h-4 text-orange-400" />
            <span className="text-orange-400 text-xs font-bold uppercase tracking-wider">
              সীমিত সময়ের অফার
            </span>
          </div>

          <h2 className="text-2xl font-bold text-white mb-2">
            {content.heading}
          </h2>
          <p className="text-white text-lg font-semibold">
            {content.description}
          </p>
          {content.sub && (
            <p className="text-orange-200 text-sm mt-2">{content.sub}</p>
          )}

          <div className="flex justify-center gap-3 text-4xl font-mono font-bold text-white my-6">
            <div className="bg-black/50 px-4 py-3 rounded-xl min-w-[70px]">
              {String(timeLeft.hours).padStart(2, "0")}
              <span className="text-xs block text-orange-300">ঘণ্টা</span>
            </div>
            <div className="bg-black/50 px-4 py-3 rounded-xl min-w-[70px]">
              {String(timeLeft.minutes).padStart(2, "0")}
              <span className="text-xs block text-orange-300">মিনিট</span>
            </div>
            <div className="bg-black/50 px-4 py-3 rounded-xl min-w-[70px]">
              {String(timeLeft.seconds).padStart(2, "0")}
              <span className="text-xs block text-orange-300">সেকেন্ড</span>
            </div>
          </div>

          <button
            onClick={handleRegister}
            className=" flex justify-center items-center gap-2 w-full bg-gradient-to-r from-orange-500 to-red-600 text-white font-bold py-3 px-6 rounded-full hover:shadow-lg transition transform hover:scale-[1.02]"
          >
            {content.button}

            <MdArrowForward className="text-lg group-hover:translate-x-1 transition-transform duration-300" />
          </button>
        </div>
      </div>
      </div>

    </>
  );
}
